import React, { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

const NAV_ITEMS = [
  { path:'/dashboard', icon:'📊', label:'Tableau de bord' },
  { path:'/projects', icon:'🏗️', label:'Projets' },
  { path:'/contracts/upload', icon:'📄', label:'Analyser contrat' },
];

export default function AppLayout({ children }) {
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const handleLogout = () => {
    logout();
    toast.success('Déconnecté avec succès');
    navigate('/');
  };

  const Sidebar = () => (
    <aside style={{
      width: 240, background:'#0D0D1A',
      borderRight:'1px solid rgba(255,255,255,0.07)',
      display:'flex', flexDirection:'column',
      height:'100vh', position:'sticky', top:0, flexShrink:0,
    }}>
      {/* Logo */}
      <div style={{ padding:'24px 20px', borderBottom:'1px solid rgba(255,255,255,0.07)' }}>
        <Link to="/dashboard" style={{ display:'flex', alignItems:'center', gap:10, textDecoration:'none' }}>
          <div style={{ width:34, height:34, background:'linear-gradient(135deg, #F59E0B, #D97706)', borderRadius:6, display:'flex', alignItems:'center', justifyContent:'center', fontSize:16, fontWeight:900, color:'#0D0D1A', fontFamily:'Bebas Neue' }}>C</div>
          <span style={{ fontFamily:'Bebas Neue', fontSize:22, letterSpacing:2, color:'#fff' }}>CHANTIER<span style={{ color:'#F59E0B' }}>360</span></span>
        </Link>
      </div>

      {/* Nav */}
      <nav style={{ flex:1, padding:'16px 12px', display:'flex', flexDirection:'column', gap:4 }}>
        {NAV_ITEMS.map(item => {
          const active = location.pathname === item.path || (item.path !== '/dashboard' && location.pathname.startsWith(item.path));
          return (
            <Link key={item.path} to={item.path} style={{
              display:'flex', alignItems:'center', gap:12,
              padding:'10px 12px', borderRadius:8,
              textDecoration:'none',
              background: active ? 'rgba(245,158,11,0.12)' : 'transparent',
              color: active ? '#F59E0B' : '#9CA3AF',
              fontFamily:'Barlow Condensed', fontSize:15, fontWeight:600,
              letterSpacing:0.3, transition:'all 0.2s',
              borderLeft: active ? '3px solid #F59E0B' : '3px solid transparent',
            }}>
              <span style={{ fontSize:16 }}>{item.icon}</span>
              {item.label}
            </Link>
          );
        })}
      </nav>

      {/* User */}
      <div style={{ padding:'16px 20px', borderTop:'1px solid rgba(255,255,255,0.07)' }}>
        <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:12 }}>
          <div style={{
            width:36, height:36, borderRadius:'50%',
            background:'linear-gradient(135deg, #F59E0B, #D97706)',
            display:'flex', alignItems:'center', justifyContent:'center',
            fontSize:14, fontWeight:700, color:'#0D0D1A', fontFamily:'Bebas Neue', flexShrink:0,
          }}>
            {user?.full_name?.[0]?.toUpperCase() || 'U'}
          </div>
          <div style={{ overflow:'hidden' }}>
            <p style={{ fontSize:13, fontWeight:600, color:'#fff', margin:0, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{user?.full_name}</p>
            <p style={{ fontSize:11, color:'#6B7280', margin:0, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{user?.company_name}</p>
          </div>
        </div>
        <button onClick={handleLogout} className="btn btn-ghost btn-sm btn-full" style={{ fontSize:13 }}>
          Déconnexion
        </button>
      </div>
    </aside>
  );

  return (
    <div style={{ display:'flex', minHeight:'100vh', background:'#0D0D1A' }}>
      <Sidebar />
      <main style={{ flex:1, overflow:'auto', minWidth:0 }}>
        {children}
      </main>
    </div>
  );
}
